*
* @framework ggLowCodeGTMKit
*/
const makeNumber = require('makeNumber');

const hoursToMilliseconds = function(timeValue) {
   const timeNum = makeNumber(timeValue);
   if (timeNum === timeNum) {
       return timeNum * 1000 * 60 * 60;
