const value = applyCast(data.pre, data.src);
return out(isUnixTimestamp(value));
*/
// ===============================================================================
// isUnixTimestamp() – Apply Mode
// ===============================================================================
return function(value) {
   return out(isUnixTimestamp(value));
};


