scenarios:
  - name: '[example] First match wins'
    code: |-
      /* @display
      Conditions: [{ 

        condition: { 
            Input Value: 'hello', 
            Custom Function: (v, r) => v === r, 
            Reference: 'hello'
            }, 
            Result: 'Match 1'
          },

          { condition: { 
            Input Value: 'world', 
            Custom Function: (v, r) => v === r, 
            Reference: 'world'
            }, 
            Result: 'Match 2'
          }
      ]
      Default Output: No match
      @output
      Match 1
      */
      const ls1 = [
          {condition: {val: 'hello', fn: (v, r) => v === r, ref: 'hello'}, res: 'Match 1'},
          {condition: {val: 'world', fn: (v, r) => v === r, ref: 'world'}, res: 'Match 2'}
      ];
      const def = 'No match';
      const mockData = {
          ls1: ls1,
          def: def,
          cast: undefined,
          out: undefined
      };
      let variableResult = runCode(mockData);
      assertThat(variableResult).isEqualTo('Match 1');
