const processedValue = applyCast(data.pre, data.val);
return out(toStringRepresentation(processedValue));
*/
// ===============================================================================
// toStringRepresentation() – Apply Mode
// ===============================================================================
return function(value) {
   return out(toStringRepresentation(value));
};


