/**
 * Extracts the protocol from a given URL.
 *
 * @param {string} data.src - The URL to extract the protocol from.
 * @param {Function|string} [data.out] - Optional output handler: function to transform result or string with format.
 *
 * Direct-mode specific parameters:
 * @param {Function} [data.pre] - Optional pre-processor function to transform src before extracting.
 * 
 * @returns {string|undefined} The protocol of the URL, or undefined if the input is invalid.
 *
 * @framework ggLowCodeGTMKit
 */

const parseUrl = require('parseUrl');

const extractProtocol = function(url) {
    const parsed = parseUrl(url);
    return parsed && parsed.protocol || undefined;
};

const safeFunction = fn => typeof fn === 'function' ? fn : x => x;
const out = safeFunction(data.out);

// ===============================================================================
// extractProtocol - Direct mode
// ===============================================================================
const applyCast = (castFn, value) => safeFunction(castFn)(value);
const value = applyCast(data.pre, data.src);
return out(extractProtocol(value));

// ===============================================================================
// extractProtocol() – Apply Mode
// ===============================================================================
/*
return function(value) {
   return out(extractProtocol(value));
};
*/


